import React from "react";

export default function About() {
  return (
    <div className="about">

      {/* HEADER */}
      <div className="hero">
        <h1>
          I design & build systems that feel <span>simple</span>, but work <span>deep</span>.
        </h1>

        <p>
          Information Technology student • Builder mindset • Problem solver
        </p>
      </div>

      {/* SPLIT LAYOUT */}
      <div className="split">

        {/* LEFT: IDENTITY */}
        <div className="left">

          <div className="block">
            <h2>🧠 How I Think</h2>
            <p>
              I don’t start with code. I start with structure — breaking problems
              into logical systems and understanding how each part interacts.
            </p>
          </div>

          <div className="block accent">
            <h2>⚡ My Approach</h2>
            <p>
              Build → Break → Improve → Repeat. I learn by iteration, not theory.
              Every project is a step toward better clarity in engineering thinking.
            </p>
          </div>

          <div className="block">
            <h2>🎯 What Drives Me</h2>
            <p>
              I enjoy turning messy ideas into clean, usable systems that actually
              solve real problems instead of just looking good.
            </p>
          </div>

        </div>

        {/* RIGHT: PROOF */}
        <div className="right">

          <div className="card glow">
            <h2>🎓 Education</h2>

            <h3>B.Tech – Information Technology</h3>
            <p className="muted">Panimalar Engineering College</p>

            <div className="meta">
              <span>2023 → 2027</span>
              <span className="cgpa">CGPA: 8.81</span>
            </div>
          </div>

          <div className="card">
            <h2>🚀 Focus Areas</h2>
            <p>
              Full Stack Development • System Design Basics • UI Engineering • AI Exploration
            </p>
          </div>

          <div className="card highlight">
            <h2>📌 Current Direction</h2>
            <p>
              Building scalable web applications and improving architectural thinking
              through real-world project development.
            </p>
          </div>

        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .about {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        /* HERO */
        .hero h1 {
          font-size: 42px;
          line-height: 1.3;
        }

        .hero span {
          color: #38BDF8;
        }

        .hero p {
          color: #94a3b8;
          margin-top: 10px;
        }

        /* SPLIT */
        .split {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 40px;
          margin-top: 40px;
        }

        /* LEFT SIDE (no heavy cards) */
        .block {
          margin-bottom: 25px;
        }

        .block h2 {
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .block p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        .accent {
          padding-left: 14px;
          border-left: 2px solid rgba(56,189,248,0.5);
        }

        /* RIGHT SIDE CARDS */
        .right {
          display: flex;
          flex-direction: column;
          gap: 18px;
        }

        .card {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(255,255,255,0.06);
        }

        .glow {
          border: 1px solid rgba(56,189,248,0.3);
          box-shadow: 0 0 25px rgba(56,189,248,0.15);
        }

        .highlight {
          background: linear-gradient(135deg, rgba(56,189,248,0.1), transparent);
        }

        h2 {
          color: #38BDF8;
          margin-bottom: 8px;
        }

        h3 {
          margin: 0;
          font-size: 18px;
        }

        .muted {
          color: #94a3b8;
        }

        .meta {
          display: flex;
          justify-content: space-between;
          margin-top: 10px;
          color: #cbd5e1;
          font-size: 13px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .split {
            grid-template-columns: 1fr;
          }

          .hero h1 {
            font-size: 32px;
          }
        }

      `}</style>

    </div>
  );
}
